import{az as e,P as s,Q as a,aQ as i}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const m=JSON.parse('{"title":"Cookie 与 Session 的跨域名共享规则","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/浏览器/Cookie与Session的跨域名共享规则.md","filePath":"面试题/浏览器/Cookie与Session的跨域名共享规则.md","lastUpdated":1782478366000}'),n={name:"面试题/浏览器/Cookie与Session的跨域名共享规则.md"};function r(t,o,d,l,c,h){return s(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="cookie-与-session-的跨域名共享规则" tabindex="-1">Cookie 与 Session 的跨域名共享规则 <a class="header-anchor" href="#cookie-与-session-的跨域名共享规则" aria-label="Permalink to “Cookie 与 Session 的跨域名共享规则”">​</a></h1><p>直接给出明确结论，分两种核心场景：</p><ol><li><p><strong>同根域名场景（<strong><strong><code>shturl.</code></strong></strong> 和 <strong><strong><code>a.shturl.</code></strong></strong>、<strong><strong><code>b.shturl.</code></strong></strong>）</strong>：默认不能直接共享，但通过配置 Cookie 的 <code>Domain</code> 属性，可以实现全子域名共享 Cookie，进而共享 Session。</p></li><li><p><strong>完全不同根域名场景（<strong><strong><code>shturl.</code></strong></strong> 和 <strong><strong><code>yyy.com</code></strong></strong>）</strong>：浏览器同源策略严格禁止，任何前端 / 后端手段都无法直接互相读取或共享 Cookie，Session 自然也无法直接共享。</p></li></ol><hr><h2 id="一、cookie-的域名隔离规则-权威标准" tabindex="-1">一、Cookie 的域名隔离规则（权威标准） <a class="header-anchor" href="#一、cookie-的域名隔离规则-权威标准" aria-label="Permalink to “一、Cookie 的域名隔离规则（权威标准）”">​</a></h2><p>根据 MDN HTTP Cookie 规范，Cookie 的作用域完全由 <code>Domain</code> 和 <code>Path</code> 属性控制，其中域名是核心隔离边界。</p><h3 id="_1-默认行为-不跨子域名-host-only" tabindex="-1">1. 默认行为：不跨子域名（Host-only） <a class="header-anchor" href="#_1-默认行为-不跨子域名-host-only" aria-label="Permalink to “1. 默认行为：不跨子域名（Host-only）”">​</a></h3><p>如果设置 Cookie 时<strong>不指定 <strong><strong><code>Domain</code></strong></strong> 属性</strong>，该 Cookie 为「主机专属 Cookie」：</p><ul><li><p>仅对设置它的当前域名有效，<strong>不包含任何子域名</strong>。</p></li><li><p>例：在 <code>shturl.</code> 种下的 Cookie，<code>a.shturl.</code>、<code>b.shturl.</code> 的请求不会自动携带，前端 JS 也无法读取。</p></li><li><p>反向同理：<code>a.shturl.</code> 种下的 Cookie，<code>shturl.</code> 默认也拿不到。</p></li></ul><h3 id="_2-配置-domain-后-同根域名全域共享" tabindex="-1">2. 配置 Domain 后：同根域名全域共享 <a class="header-anchor" href="#_2-配置-domain-后-同根域名全域共享" aria-label="Permalink to “2. 配置 Domain 后：同根域名全域共享”">​</a></h3><p>设置 <code>Domain=shturl.</code> 后，Cookie 会对 <code>shturl.</code> 本身及其所有子域名（<code>a.shturl.</code>、<code>b.shturl.</code>、任意层级子域名）生效：</p><ul><li><p>浏览器请求任意匹配的子域名时，都会自动携带该 Cookie；</p></li><li><p>未开启 <code>HttpOnly</code> 的 Cookie，各子域名的前端 JS 均可读取。</p></li></ul><blockquote><p>补充说明：早期规范要求域名前加小数点（<code>.shturl.</code>），现代浏览器已忽略前导点，<code>Domain=shturl.</code> 和 <code>Domain=.shturl.</code> 效果完全一致，均包含所有子域名。</p></blockquote><h3 id="_3-不同根域名-绝对隔离" tabindex="-1">3. 不同根域名：绝对隔离 <a class="header-anchor" href="#_3-不同根域名-绝对隔离" aria-label="Permalink to “3. 不同根域名：绝对隔离”">​</a></h3><p>这是浏览器的安全底线，没有任何绕过方式：</p><ul><li><p><code>shturl.</code> 和 <code>yyy.com</code> 属于完全独立的根域名，双方 Cookie 完全隔离，互不读取、互不携带。</p></li><li><p>服务端也无法跨域名设置 Cookie：在 <code>shturl.</code> 的响应中写 <code>Domain=yyy.com</code>，浏览器会直接拒绝保存这条 Cookie。</p></li><li><p>额外说明：Cookie 不区分端口，同一域名下不同端口的服务共享同一套 Cookie。</p></li></ul><h3 id="_4-domain-设置的安全限制" tabindex="-1">4. Domain 设置的安全限制 <a class="header-anchor" href="#_4-domain-设置的安全限制" aria-label="Permalink to “4. Domain 设置的安全限制”">​</a></h3><p>浏览器有严格校验，不符合规则的 Cookie 会被直接丢弃：</p><ul><li><p>只能设置为当前域名本身，或其上级根域名；</p></li><li><p>不能设置为其他无关域名，不能设置为公共顶级域名（如 <code>.com</code>、<code>.cn</code>）。</p></li></ul><hr><h2 id="二、session-的跨域名共享逻辑" tabindex="-1">二、Session 的跨域名共享逻辑 <a class="header-anchor" href="#二、session-的跨域名共享逻辑" aria-label="Permalink to “二、Session 的跨域名共享逻辑”">​</a></h2><p>Session 的核心机制是：<strong>服务端存储会话数据，客户端 Cookie 存储 sessionId</strong>。因此 Session 能不能跨域名共享，本质上就是 <code>sessionId</code> 这个 Cookie 能不能跨域名传递。</p><h3 id="_1-同根域名下-可实现-session-共享-两步配置" tabindex="-1">1. 同根域名下：可实现 Session 共享（两步配置） <a class="header-anchor" href="#_1-同根域名下-可实现-session-共享-两步配置" aria-label="Permalink to “1. 同根域名下：可实现 Session 共享（两步配置）”">​</a></h3><p>这是企业级多子域名系统最常用的「全站登录」方案，实现成本极低：</p><ol><li><p><strong>Cookie 层</strong>：服务端设置 sessionId Cookie 时，指定 <code>Domain</code> 为根域名（如 <code>shturl.</code>），让所有子域名都能读取到同一个 sessionId。</p></li><li><p><strong>存储层</strong>：所有子域名对应的后端服务，共用同一个 Session 存储（通常是 Redis 集群），用同一个 sessionId 查询同一份会话数据。</p></li></ol><p>最终效果：用户在 <code>shturl.</code> 登录后，直接访问 <code>a.shturl.</code>、<code>b.shturl.</code> 自动处于登录状态，无需二次登录。</p><h3 id="_2-不同根域名下-无法直接共享-session" tabindex="-1">2. 不同根域名下：无法直接共享 Session <a class="header-anchor" href="#_2-不同根域名下-无法直接共享-session" aria-label="Permalink to “2. 不同根域名下：无法直接共享 Session”">​</a></h3><p>由于 sessionId 的 Cookie 跨根域名完全隔离，服务端无法拿到同一个会话标识，自然无法直接共享登录态。 这种场景必须使用标准的 <strong>SSO（单点登录）</strong> 方案，例如 OAuth2.0、CAS 中央认证服务，通过跳转授权的方式同步各域名的登录状态。</p><hr><h2 id="三、关键补充说明" tabindex="-1">三、关键补充说明 <a class="header-anchor" href="#三、关键补充说明" aria-label="Permalink to “三、关键补充说明”">​</a></h2><h3 id="_1-samesite-属性不影响同根子域名共享" tabindex="-1">1. SameSite 属性不影响同根子域名共享 <a class="header-anchor" href="#_1-samesite-属性不影响同根子域名共享" aria-label="Permalink to “1. SameSite 属性不影响同根子域名共享”">​</a></h3><p>Cookie 的 <code>SameSite</code> 属性用于控制<strong>跨站请求</strong>是否携带 Cookie。同根域名的子域名之间属于「同站（Same-site）」，因此 <code>SameSite=Lax</code> / <code>Strict</code> 都不会阻止子域名间的 Cookie 携带。</p><h3 id="_2-httponly-不影响共享-只限制读取" tabindex="-1">2. HttpOnly 不影响共享，只限制读取 <a class="header-anchor" href="#_2-httponly-不影响共享-只限制读取" aria-label="Permalink to “2. HttpOnly 不影响共享，只限制读取”">​</a></h3><p>开启 <code>HttpOnly</code> 后，前端 JS 无法读取 Cookie，但浏览器发起请求时仍会自动携带，完全不影响子域名间的 Cookie 共享和 Session 鉴权，反而能防御 XSS 窃取，安全性更高。</p><h3 id="_3-本地开发的特殊情况" tabindex="-1">3. 本地开发的特殊情况 <a class="header-anchor" href="#_3-本地开发的特殊情况" aria-label="Permalink to “3. 本地开发的特殊情况”">​</a></h3><p><code>localhost</code> 属于特殊主机名，浏览器通常不支持直接设置 <code>Domain=localhost</code> 来共享子域名。本地测试多子域名场景时，建议修改系统 hosts 文件，映射 <code>local.com</code>、<code>a.local.com</code> 这类模拟域名进行调试。</p><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>你举的 <code>shturl.</code>、<code>a.shturl.</code>、<code>b.shturl.</code> 场景，<strong>只要配置 Cookie 的 Domain 为根域名，就能共享 Cookie 和 Session</strong>，默认不配置则不行；只有完全不同的根域名之间，才是真正的无法共享。</p><p>需要我给你一份 Express + express-session 实现子域名共享 Session 的完整配置代码吗？</p><blockquote><p>（注：部分内容可能由 AI 生成）</p></blockquote>',41)])])}const _=e(n,[["render",r]]);export{m as __pageData,_ as default};
